    if (['clone', 'speech-to-speech'].includes(voiceForm.source_type) && voiceForm.consent_status !== 'consent-verified') { onNotice('Clone / Speech-to-speech 必须先提供并核验授权证据；Voice Design 不需要真人授权。'); return; }
    const voiceId = nextId('V', voices);
    const languageBoost = localeLanguageBoost(voiceForm.locale, voiceForm.language);
    const selectedVoice = selectedCatalogVoice;
    const profile: AudioVoiceProfile = { id: voiceId, character_id: voiceForm.character_id.trim() || null, role: voiceForm.role, name, source_type: voiceForm.source_type, provider: selectedTtsRoute?.provider || ttsCapability?.provider || 'minimax', model: selectedTtsRoute?.model || ttsCapability?.model || 'speech-2.8-hd', provider_profile_id: voiceForm.provider_profile_id || selectedTtsRoute?.provider_profile_id || ttsCapability?.provider_profile_id || null, provider_voice_id: voiceForm.provider_voice_id.trim() || undefined, provider_voice_name: voiceForm.provider_voice_name.trim() || selectedVoice?.name || '', provider_voice_source: selectedVoice?.source || 'system', provider_region: voiceForm.provider_region, locale: voiceForm.locale.trim(), language_boost: languageBoost || null, language: voiceForm.language.trim(), dialect: voiceForm.dialect.trim(), traits: splitTags(voiceForm.traits), pronunciation_risks: splitTags(voiceForm.pronunciation_risks), register: voiceForm.register.trim(), age_range: voiceForm.age_range.trim(), pitch_energy: voiceForm.pitch_energy.trim(), breath_noise_profile: voiceForm.breath_noise_profile.trim(), consent_status: voiceForm.source_type === 'preset' ? 'not-required' : voiceForm.consent_status, consent_evidence_ref: voiceForm.consent_evidence_ref.trim(), allowed_use: voiceForm.allowed_use.trim(), geography: voiceForm.geography.trim(), term: voiceForm.term.trim(), provider_eligibility: voiceForm.provider_eligibility.trim(), logical_asset_id: voiceForm.logical_asset_id || null, selected_audition_id: null, catalog_snapshot: selectedVoice ? { ...selectedVoice, region: voiceForm.provider_region, catalog_status: minimaxCatalog?.status } : {}, continuity_anchor: { locale: voiceForm.locale.trim(), language: voiceForm.language.trim(), dialect: voiceForm.dialect.trim(), provider_voice_id: voiceForm.provider_voice_id.trim(), register: voiceForm.register.trim(), pitch_energy: voiceForm.pitch_energy.trim() }, status: 'draft', notes: voiceForm.notes.trim() };
    const auditionTexts = [{ condition: 'neutral', text: voiceForm.neutral_text, emotion: '', direction: '自然日常说话，保持清楚、平稳，不额外夸张情绪。' }, { condition: 'emotional', text: voiceForm.emotional_text, emotion: 'happy', direction: '保持同一音色，增加轻微期待感和明亮句尾，不提高到尖锐或动漫腔。' }, { condition: 'pronunciation-stress', text: voiceForm.pronunciation_text, emotion: '', direction: '保持自然速度，清晰读出长音、促音和句尾，不添加额外词语。' }] as const;
    const newAuditions: AudioAudition[] = auditionTexts.map((item, index) => ({ id: `AUD${String(auditions.length + index + 1).padStart(3, '0')}`, voice_id: voiceId, character_id: profile.character_id, condition: item.condition, text: item.text.trim(), source_text: item.text.trim(), provider_text: item.text.trim(), text_status: 'candidate', locale: profile.locale, language: profile.language, dialect: profile.dialect, language_boost: profile.language_boost, provider_region: profile.provider_region, variant: item.condition, emotion: item.emotion, instructions: [item.direction, voiceForm.audition_instructions.trim()].filter(Boolean).join('；'), target_duration: null, artifact_id: null, qa_run_id: null, provider_profile_id: profile.provider_profile_id || null, provider: 'minimax', model: profile.model, status: selectedTtsRoute?.ready && profile.provider_voice_id ? 'user-confirmation-required' : 'external-execution-pending', notes: '首轮三组使用同一句原始台词；只改变试听方向，不添加控制标签。结果必须单独 QA Approved 后才能锁定声音身份。' }));
