  const createAudioAsset = async (kind: 'audio' | 'music' | 'sfx') => { const name = window.prompt(`新建${kind === 'audio' ? '对白/声音' : kind === 'music' ? '音乐' : '音效'}逻辑资产名称`); if (!name?.trim()) return; const id = await onCreateAsset(kind, name.trim(), kind === 'audio' ? 'dialogue' : kind === 'music' ? 'music-cue' : 'sfx'); if (id) onNotice(`已创建 ${id}；请刷新后在对应表单中选择。`); };
  const addCue = () => { if (!cueForm.purpose.trim()) { onNotice('请先填写音乐 Cue 的叙事功能。'); return; } const cue: AudioMusicCue = { id: nextId('CUE', cues), asset_id: cueForm.asset_id || null, shot_ids: splitIds(cueForm.shot_ids), purpose: cueForm.purpose.trim(), entry: cueForm.entry.trim(), development: cueForm.development.trim(), exit: cueForm.exit.trim(), duration: cueForm.duration ? Number(cueForm.duration) : null, bpm: cueForm.bpm ? Number(cueForm.bpm) : null, instrumentation: cueForm.instrumentation.trim(), texture: cueForm.texture.trim(), dialogue_avoidance: [], rights_status: cueForm.rights_status, execution_status: musicCapability?.ready ? 'user-confirmation-required' : 'external-execution-pending', provider_hint: cueForm.provider_hint.trim(), notes: cueForm.notes.trim() }; mutate((current) => ({ ...current, music_cues: [...(current.music_cues || []), cue] })); setCueForm((current) => ({ ...current, purpose: '', shot_ids: '', duration: '', bpm: '', instrumentation: '', texture: '', development: '', notes: '' })); onNotice(`${cue.id} 已建立；${musicCapability?.ready ? '音乐 Provider 已就绪。' : '当前使用 provider-neutral Cue。'}`); };
