  const importAudio = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; if (!importForm.asset_id) { onNotice('请先选择逻辑资产，再导入文件。'); return; } const form = new FormData(); form.append('file', file, file.name); form.append('logical_asset_id', importForm.asset_id); form.append('asset_class', importForm.kind); form.append('asset_role', importForm.role); form.append('source_type', 'local-upload'); form.append('relevant_shots_json', JSON.stringify([])); form.append('run_audit', 'true'); form.append('authorization_status', importForm.authorization_status); try { const result = await studioApi.intakeAsset(projectId, form); await onRefresh(); const id = String(result.artifact?.id || result.artifact_id || ''); if (importForm.target_id && id) mutate((current) => ({ ...current, auditions: current.auditions?.map((item) => item.id === importForm.target_id ? { ...item, artifact_id: id, status: 'generated-pending-qa' } : item), takes: current.takes?.map((item) => item.id === importForm.target_id ? { ...item, artifact_id: id, status: 'generated-pending-qa' } : item), voice_references: current.voice_references?.map((item) => item.id === importForm.target_id ? { ...item, artifact_id: id } : item) })); onNotice(`${file.name} 已导入为 ${id || '候选版本'}；现在仍需声音 QA 和登记。`); } catch (error) { onNotice((error as Error).message); } };

