    {mode === 'creator' && <AudioVoiceDesignWorkbench projectId={projectId} document={draft} routes={ttsRoutes} defaultRoute={defaultTtsRoute} designSeed={creatorVoiceDesign} revision={envelope.revision} dirty={dirty} saving={busy || saving} onServerDocument={applyCreatorServerDocument} onPersist={() => save()} onRefresh={onRefresh} onNotice={onNotice} />}
